#include <Arduino.h>
#include <TM1637Display.h>
#include <math.h>

TM1637Display display(4, 5);
float currentTemperature = 0.0f;
float maximumTemperature = 0.0f;
bool haveTemperature = false;
bool historyActive = false;
unsigned long historyStarted = 0;
unsigned long lastSample = 0;
unsigned long lastReport = 0;
unsigned long buttonChanged = 0;
int rawButton = HIGH;
int stableButton = HIGH;

void sampleTemperature() {
  currentTemperature = analogRead(A1) * (500.0f / 1023.0f);
  if (!haveTemperature || currentTemperature > maximumTemperature) {
    maximumTemperature = currentTemperature;
  }
  haveTemperature = true;
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  Serial.begin(9600);
  display.setBrightness(7);
  sampleTemperature();
}

void loop() {
  unsigned long now = millis();
  if (now - lastSample >= 100) {
    lastSample = now;
    sampleTemperature();
  }
  int reading = digitalRead(2);
  if (reading != rawButton) {
    rawButton = reading;
    buttonChanged = now;
  }
  if (now - buttonChanged >= 30 && stableButton != rawButton) {
    stableButton = rawButton;
    if (stableButton == LOW) {
      historyActive = true;
      historyStarted = now;
    }
  }
  if (historyActive && now - historyStarted >= 3000) {
    historyActive = false;
  }
  float shown = historyActive ? maximumTemperature : currentTemperature;
  display.showNumberDec((int)lroundf(shown), false);
  if (now - lastReport >= 250) {
    lastReport = now;
    Serial.print("Current: ");
    Serial.print(currentTemperature, 2);
    Serial.print(" Maximum: ");
    Serial.println(maximumTemperature, 2);
  }
}
